CREATE TAG gov.tags.pii_class ALLOWED_VALUES 'direct', 'quasi';

CREATE MASKING POLICY gov.policies.mask_str AS (val STRING) RETURNS STRING ->
  CASE WHEN IS_ROLE_IN_SESSION('PII_READER') THEN val
       ELSE '*** masked ***' END;

ALTER TAG gov.tags.pii_class SET MASKING POLICY gov.policies.mask_str;
ALTER TABLE gold.dim_customer MODIFY COLUMN postcode
  SET TAG gov.tags.pii_class = 'quasi';

CREATE ROW ACCESS POLICY gov.policies.by_country
  AS (row_country STRING) RETURNS BOOLEAN ->
  IS_ROLE_IN_SESSION('COMPLIANCE_ALL')
  OR EXISTS (SELECT 1 FROM gov.entitlements e
             WHERE e.role_name = CURRENT_ROLE()
               AND e.country = row_country);
ALTER TABLE gold.fct_transactions
  ADD ROW ACCESS POLICY gov.policies.by_country ON (country_code);

contract: payments.card_transactions
version: 3.1.0
owner: payments-platform-team
consumers: [finance-data-team, risk-analytics-team]
fields:
  - {name: transaction_id, type: string, required: true, unique: true}
  - {name: customer_id, type: string, classification: direct}
  - {name: amount_minor, type: integer, required: true}
  - {name: currency, type: string, pattern: "^[A-Z]{3}$"}
  - {name: booked_at, type: timestamp, timezone: UTC}
sla: {freshness: 15m, completeness_check: daily_ledger_reconciliation}
change_policy: breaking changes need a new major version and
  30 days of dual publishing
